parameters.jsCode:
// 1. THE SPIRITUAL SOUL (Amharic Wisdom)
const spiritualQuotes = [
  { amharic: "እግዚአብሔር ብርሃኔና መድኃኒቴ ነው፤ የሚያስፈራኝ ማን ነው?", english: "The Lord is my light and my salvation; whom shall I fear?" },
  { amharic: "በጸሎት የሚተጋ ሰው አያፍርም።", english: "He who perseveres in prayer shall not be ashamed." },
  { amharic: "ቅዱስ እግዚአብሔር ሆይ፥ ማረን።", english: "Holy God, have mercy on us." },
  { amharic: "ፍቅር ሁሉን ያሸንፋል።", english: "Love conquers all." },
  { amharic: "ትዕግስት የነፍስ መድኃኒት ናት።", english: "Patience is the medicine of the soul." },
  { amharic: "ለእግዚአብሔር የሚሳነው ነገር የለም።", english: "Nothing is impossible for God." },
  { amharic: "ሰማያት የእግዚአብሔርን ክብር ይናገራሉ።", english: "The heavens declare the glory of God." },
  { amharic: "በሰላም እተኛለሁ በሰላምም እነቃለሁ።", english: "I will both lie down in peace, and sleep." },
  { amharic: "ምሕረትህ ከሕይወት ይሻላል።", english: "Your loving-kindness is better than life." },
  { amharic: "እግዚአብሔር ፍቅር ነው።", english: "God is love." }
];

// 2. THE VISUAL SCENE
const scenes = [
  "A lone priest praying in the deep blue shadows of Lalibela rock churches",
  "An elderly monk reading a glowing ancient manuscript under a Baobab tree",
  "Silhouettes of a pilgrimage climbing a misty mountain towards a monastery",
  "A close-up of a hand holding a traditional Ethiopian silver cross",
  "Divine rays of light hitting a church altar filled with incense smoke",
  "A peaceful waterfall in the Simien Mountains with a rainbow mist",
  "Ancient Orthodox murals on a weathered stone ceiling, flickering candlelight",
  "A monk meditating on a cliff edge overlooking a vast Ethiopian canyon",
  "Golden wheat fields under a massive starry night sky in the highlands",
  "A traditional jebena coffee ceremony during a peaceful Sunday morning"
];

// 3. THE ARTISTIC VIBE
const styles = [
  "Cinematic 9:16, 8k, Unreal Engine 5 style, hyper-realistic",
  "Ethereal oil painting, soft brushstrokes, golden hour glow",
  "Vintage 35mm film photography, grainy, moody, National Geographic style",
  "Magical realism, floating embers, divine lighting, sharp focus",
  "Ancient parchment texture, warm sepia tones, spiritual atmosphere"
];

// --- GENERATION LOGIC ---
const quote = spiritualQuotes[Math.floor(Math.random() * spiritualQuotes.length)];
const scene = scenes[Math.floor(Math.random() * scenes.length)];
const style = styles[Math.floor(Math.random() * styles.length)];

// Random Seed
const seed = Math.floor(Math.random() * 1000000000).toString();

// TEXT OVERLAY INSTRUCTION
// We tell the AI to include the text as a centered, elegant glowing caption.
const textInstruction = `The image must feature the following Amharic text centered at the bottom in an elegant, glowing golden Ge'ez font: "${quote.amharic}"`;

return [{
  json: {
    prompt: `${scene}, ${style}, deeply spiritual. ${textInstruction}`,
    amharic_text: quote.amharic,
    english_translation: quote.english,
    seed: seed
  }
}];

